{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사 발화에서 '죄송해요'라고 한 순간이 이 방에서 그대로 일어나고 있다고 지적함. 내담자가 자신의 욕구를 표현하려는 순간 스스로를 처벌하는 패턴이 '나를 앞세우는 것은 이기적인 일이다'라는 핵심신념과 직결됨. 내담자가 '원하는 걸 알아차리는 것 자체가 무서웠다'고 한 것도 이 신념에서 비롯."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "'참으면 되는 거고, 참다가 가끔 터지면 그건 제가 약한 거라고 생각했어요'라는 자기희생 패턴이 상담사 발화의 핵심 주제. '당연한 거'라는 말이 낯설다는 반응은 평생 자기희생만 해온 사람의 반응으로, 성장경험과 상황 사례(명절 준비를 당연하게 맡김)와 연결."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/situations/1"],
      "relevance": "'왜 아무도 나한테는 힘들냐고 안 물어보지'라는 생각이 차 안에서 스쳤다는 내담자 진술과, 상담사가 '누가 나한테 당연하다고 말해주는 게 낯설다'고 한 것이 모두 타인중심성(자기 욕구를 알아차리지 못하는 상태)과 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '죄송해요'라고 한 순간을 지적한 것은, 내담자가 내 필요나 힘듦을 말하려는 순간 '이기적이고 부끄러운 일'로 자동 전환하는 태도가 상담실 안에서 실시간으로 작동하고 있음을 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "'원하는 걸 알아차리는 것 자체가 무서웠다'는 진술이 이 부정적 가정(욕구를 주장하면 이기적인 사람으로 여겨져 비난받음)의 정서적 핵심을 정확히 드러냄. 상담사의 '그 무서움이 어디서 왔는지' 질문과 연결."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": [],
      "relevance": "'힘들면 참으면 되는 거고'라는 내담자 진술이 '힘들어도 내색하지 않아야 한다'는 규칙과 일치. 상담사가 이 규칙을 '허락이 안 되는 느낌'으로 명명함."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1"],
      "relevance": "상담사가 '죄송하다'고 한 순간을 지적한 것은, 자신의 상태(피로, 서운함)를 드러내려다 곧바로 숨기는 대처가 상담 대화 안에서 반복되고 있음을 포착한 것. 상황 사례에서 '피곤해서 그래'라고 숨긴 패턴과 동일."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "'차에서 집에 돌아가는 길에 왜 아무도 나한테는 힘들냐고 안 물어보지'라는 생각이 스쳤다는 것은, 쌓인 서운함이 내부에서 팽팽해지고 있음을 보여주며, 이것이 결국 아이에게 소리를 지르는 폭발로 이어진 사이클(상황 사례 1의 서운함·죄책감 순환)과 연결됨."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "'돌봄을 받는 것보다 주는 역할에만 익숙함'이라는 정의가 '당연한 거라는 말이 낯설다'는 반응과 직접 연결. 상황 사례 3(배우자가 '뭘 좋아하는지도 모르겠다'고 한 것)이 이 정의를 현실에서 보여주는 사례."
    }
  ]
}

